package edu.pe.cibertec.saibm.inventario.infrastructure.persistence; import jakarta.persistence.*; import edu.pe.cibertec.saibm.inventario.domain.model.Stock; @Entity @Table(name="inventory_stock") public class StockJpaEntity {@Id @Column(name="book_id",length=200) String bookId; @Column(name="total_stock",nullable=false) int totalStock; @Column(name="available_stock",nullable=false) int availableStock; protected StockJpaEntity(){} StockJpaEntity(Stock s){apply(s);} Stock domain(){return new Stock(bookId,totalStock,availableStock);} void apply(Stock s){bookId=s.bookId();totalStock=s.totalStock();availableStock=s.availableStock();} }
